/* From Uiverse.io by Javierrocadev - Source: Javierrocadev - Tags: phone, card hover, 3d card */
.__UIV_SCOPE__ .card {
  width: 164px;
  height: 276px;
  background: rgb(0, 0, 0);
  border: 3px solid rgb(17, 4, 94);
  border-radius: 15px;
  position: relative;
  padding: 5px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  transition: all 1s ease;
  color: antiquewhite;
}

.__UIV_SCOPE__ .card::before {
  content: "";
  width: 10px;
  height: 10px;
  position: absolute;
  bottom: 10px;
  right: 77px;
  border-radius: 50%;
  background-color: rgb(17, 4, 94);
}

.__UIV_SCOPE__ .card__date {
  display: flex;
  flex-direction: column;
  margin-top: 30px;
}

.__UIV_SCOPE__ .time {
  font-size: 2em;
}

.__UIV_SCOPE__ .popup {
  background-color: #444746;
  border-radius: 5px;
  display: flex;
  flex-direction: column;
  font-size: .8em;
  padding: 3px;
}

.__UIV_SCOPE__ .popup .title {
  font-size: 9px;
  color: #9cbde2;
}

.__UIV_SCOPE__ .card__date, .__UIV_SCOPE__ .popup {
  opacity: 0;
  transition: all .5s ease;
}

.__UIV_SCOPE__ .card:hover {
  transform: rotate3d(5, 5, 10, -45deg);
}

.__UIV_SCOPE__ .card:hover .card__date, .__UIV_SCOPE__ .card:hover .popup {
  opacity: 1;
}
